import { Log } from '../log';
export const forwardMediaParserControllerToWorker = (controller) => {
    return (message) => {
        if (message.type === 'request-pause') {
            controller.pause();
            return;
        }
        if (message.type === 'request-resume') {
            controller.resume();
            return;
        }
        if (message.type === 'request-abort') {
            controller.abort();
            return;
        }
        const msg = `Unknown message type: ${message.type}`;
        Log.error(msg);
        throw new Error(msg);
    };
};
